#include <stdint.h>

#include "clock_init.h"
#include "bsp_gpio.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif


int main(void)
{
	// 將系統時脈切到 72 MHz
	// 對 GPIO 的影響： 本課的 GPIO 不依賴 72 MHz，用 8 MHz 也能動。
	// 放在最前面，是因為「開機先把時脈定好」是所有專案的慣例。
	uint32_t clock_state;
	clock_state = Clock_Init();
	while (clock_state != CLOCK_OK)
	{
		/**/
	}

	// 進行 GPIO 初始化
	// 1. 啟動 GPIOB & GPIOC 時脈
	// 2. 設定 PC13 功能
	// 3. 設定 PB0 功能
	BSP_GPIO_Init();

	for(;;)
	{
		// 按下按鍵時時 LED 亮，放開 LED 暗
		// 按鍵和 LED 都是 Active-Low： 按下讀到 0，寫 0 點亮。
		// if (BSP_GPIO_Button_IsPressed() == true)，BSP_GPIO_Button_IsPressed() 本身就回傳 bool
		if (BSP_GPIO_Button_IsPressed())
		{
			BSP_GPIO_Led_On();
		}
		else
		{
			BSP_GPIO_Led_Off();
		}
	}
}
